Method.Source:
/// <summary>
/// Task 182820 CB272_SalesInvoicing
/// TAMRebateTrans onactivated event to disable and enable controls
/// </summary>
/// <param name="sender">TAMRebateTrans datasource</param>
/// <param name="e">TAMRebateTrans DataSource Event Args</param>
[FormDataSourceEventHandler(formDataSourceStr(TAMRebateTrans, TAMRebateTrans), FormDataSourceEventType::Activated),
 SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void TAMRebateTrans_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    TAMRebateTrans rebateTrans = sender.cursor() as TAMRebateTrans;

    if (rebateTrans)
    {
        TAMRebateDeal rebatedeal = TAMRebateDeal::find(TAMRebateDateTrans::find(rebateTrans.RebateTransId).RebateDeal);

        boolean followTransItemGSTGroup = TAMRebatePosting::find(rebateDeal.RebatePostingId, rebateDeal.ModuleInventCustVend).METFollowTransItemGSTGroup;

        if (followTransItemGSTGroup)
        {
            sender.formRun().control(sender.formRun().controlId(formControlStr(TAMRebateTrans, TAMRebateTrans_METTaxItemGroup))).visible(true);
        }

        if (TAMRebateParameters::find().METProcessByCustRebateInvByItemType)
        {
            sender.formRun().control(sender.formRun().controlId(formControlStr(TAMRebateTrans, TAMRebateTrans_METItemTypes))).visible(true);
        }
    }
}
